#include <stdio.h>

int main(void)
{
    int a = 1, b = 2;
    int *p = &a;
    p = &b;
    *p = 9;
    printf("%d %d\n", a, b);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int x = 3;
    int *p = &x;
    int *q = p;
    *q = 7;
    printf("%d\n", *p);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int x = 4, y = 6;
    int *p = &x;
    p = &y;
    printf("%d %d %d\n", x, y, *p);
    return 0;
}

